(98, 'purchase_order', 'purchase-invoice-created-updated', 'english', 'Purchase Invoice Created/Updated (Sent to staff)', 'Purchase Invoice Created/Updated (Sent to staff)', '<span style=\\\"font-size: 12pt;\\\"> Hello !. </span><br /><br /><span style=\\\"font-size: 12pt;\\\">The Purchase Invoice {invoice_number} has a new change.</span><br /><br /><span style=\\\"font-size: 12pt;\\\"><br />Please click on the link to view information: {invoice_link}\r\n  </span><br /><br />', '{companyname} | CRM', NULL, 0, 1, 0),
(99, 'purchase_order', 'new-payment-approved', 'english', 'New Paymemt Approved(Sent to vendor)', 'New Paymemt Approved(Sent to vendor)', '<span style=\\\"font-size: 12pt;\\\"> Hello !. </span><br /><br /><span style=\\\"font-size: 12pt;\\\">The Payment of Purchase Invoice {invoice_number} has been approved</span><br /><br /><span style=\\\"font-size: 12pt;\\\"><br />Please click on the link to view information: {vendor_invoice_link}\r\n  </span><br /><br />', '{companyname} | CRM', NULL, 0, 1, 0),
(100, 'purchase_order', 'vendor-contact-forgot-password', 'english', 'Create New Password', 'Forgot Password', '<h2>Create a new password</h2>\r\n Forgot your password?<br /> To create a new password, just follow this link:<br /> <br /><a href=\"{reset_password_url}\">Reset Password</a><br /> <br /> You received this email, because it was requested by a {companyname}&nbsp;user. This is part of the procedure to create a new password on the system. If you DID NOT request a new password then please ignore this email and your password will remain the same. <br /><br /> {email_signature}', '{companyname} | CRM', NULL, 0, 1, 0),
(101, 'purchase_order', 'vendor-contact-password-reseted', 'english', 'Your password has been changed', 'Password Reset - Confirmation', '<strong><span style=\"font-size: 14pt;\">You have changed your password.</span><br /></strong><br /> Please, keep it in your records so you dont forget it.<br /> <br /><br /><br />If this wasnt you, please contact us.<br /><br />{email_signature}', '{companyname} | CRM', NULL, 0, 1, 0),
