(103, 'purchase_order', 'purchase-invoice-about-to-expire', 'english', 'Purchase Invoice About to Expire (Sent to staff)', 'Purchase Invoice About to Expire', '<span style=\\\"font-size: 12pt;\\\"> Hello !. </span><br /><br /><span style=\\\"font-size: 12pt;\\\">The Purchase Invoice {invoice_number}  about to expire.</span><br /><br /><span style=\\\"font-size: 12pt;\\\"><br />Please click on the link to view information: {invoice_link}\r\n  </span><br /><br />', '{companyname} | CRM', NULL, 0, 1, 0),
(104, 'inventory_warning', 'inventory-warning-to-staff', 'english', 'Inventory warning (Sent to staff)', 'Inventory warning', 'Hi {staff_name}! <br /><br />This is a inventory warning<br />{<span 12pt=\"\">notification_content</span>}. <br /><br />Regards.', '{companyname} | CRM', NULL, 0, 1, 0),
(105, 'quality', 'quality-check-send-to-staff', 'english', 'Send Quality Check to Staff', 'Quality Check {quality_check_number}', '<span>Dear {check_by_staff}</span><br /><br /><span>This email is to request your review of {operation_type}. Your feedback is crucial to ensuring we maintain high quality standards. <br /> Please find the attached quality check {quality_check_link}<br /><br /><br /><span>Kind Regards,</span><br /><span>{email_signature}<br /></span>', '{companyname} | CRM', NULL, 0, 1, 0),
(106, 'quality', 'quality-alert-send-to-staff', 'english', 'Send Quality Alert to Staff', 'Quality Alert {quality_alert_number}', '<span>Dear {alert_by_staff}</span><br /><br /><span>This email is to alert {operation_type}. Please review to ensure we maintain high quality standards. <br /> Please find the attached quality alert {quality_alert_link}<br /><br /><br /><span>Kind Regards,</span><br /><span>{email_signature}<br /></span>', '{companyname} | CRM', NULL, 0, 1, 0),
